package io.github.diodeme.ji.security.secret;

import java.util.Collection;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Structural redaction for credential-shaped fields before logging or tracing. */
public final class Redaction {
    private static final Set<String> SENSITIVE_NAMES = Set.of(
            "authorization", "api-key", "api_key", "apikey", "cookie", "set-cookie",
            "token", "access_token", "refresh_token", "client_secret", "secret", "password");

    private Redaction() {
    }

    public static Map<String, String> redact(Map<String, String> values) {
        var result = new java.util.LinkedHashMap<String, String>();
        values.forEach((key, value) -> result.put(key, isSensitive(key) ? "[REDACTED]" : value));
        return Map.copyOf(result);
    }

    public static String sanitize(String value, Collection<String> knownSecrets) {
        String sanitized = value == null ? "" : value;
        for (String secret : knownSecrets) {
            if (secret != null && !secret.isEmpty()) sanitized = sanitized.replace(secret, "[REDACTED]");
        }
        return sanitized;
    }

    private static boolean isSensitive(String name) {
        String normalized = name.toLowerCase(Locale.ROOT);
        return SENSITIVE_NAMES.stream().anyMatch(normalized::contains);
    }
}
